using System;
using System.Collections.Generic;
public static class Hashing
{
    // Returns distinct original indices; null means no pair. Does not mutate input.
    public static (int Left, int Right)? TwoSum(int[] values, int target)
    {
        ArgumentNullException.ThrowIfNull(values);
        var firstIndex = new Dictionary<long, int>();
        for (int i = 0; i < values.Length; i++)
        {
            long needed = (long)target - values[i];
            if (firstIndex.TryGetValue(needed, out int j)) return (j, i);
            firstIndex.TryAdd(values[i], i);
        }
        return null;
    }
    // Compares UTF-16 code-unit frequencies, ordinally. Case and spaces matter.
    public static bool AreAnagrams(string a, string b)
    {
        ArgumentNullException.ThrowIfNull(a);
        ArgumentNullException.ThrowIfNull(b);
        if (a.Length != b.Length) return false;
        var counts = new Dictionary<char, int>();
        foreach (char c in a) counts[c] = counts.GetValueOrDefault(c) + 1;
        foreach (char c in b)
        {
            if (!counts.TryGetValue(c, out int count)) return false;
            if (count == 1) counts.Remove(c); else counts[c] = count - 1;
        }
        return counts.Count == 0;
    }
}

using System;
public static class TwoPointers
{
    // Precondition: sorted ascending. Returns zero-based indices or null.
    public static (int Left, int Right)? SortedPair(int[] values, long target)
    {
        ArgumentNullException.ThrowIfNull(values);
        int left = 0, right = values.Length - 1;
        while (left < right)
        {
            long sum = (long)values[left] + values[right];
            if (sum == target) return (left, right);
            if (sum < target) left++; else right--;
        }
        return null;
    }
    // Exact ordinal UTF-16 palindrome: no filtering or case folding.
    public static bool IsPalindrome(string text)
    {
        ArgumentNullException.ThrowIfNull(text);
        int left = 0, right = text.Length - 1;
        while (left < right)
            if (text[left++] != text[right--]) return false;
        return true;
    }
    public static void Reverse(char[] values)
    {
        ArgumentNullException.ThrowIfNull(values);
        int left = 0, right = values.Length - 1;
        while (left < right)
        {
            (values[left], values[right]) = (values[right], values[left]);
            left++; right--;
        }
    }
    // Stable in-place compaction; prefix [0, returned length) contains nonzero values.
    public static int CompactNonzero(int[] values)
    {
        ArgumentNullException.ThrowIfNull(values);
        int write = 0;
        foreach (int value in values) if (value != 0) values[write++] = value;
        return write;
    }
}

using System;
using System.Collections.Generic;
public static class Windows
{
    public static long MaxFixedSum(int[] values, int k)
    {
        ArgumentNullException.ThrowIfNull(values);
        if (k < 1 || k > values.Length) throw new ArgumentOutOfRangeException(nameof(k));
        long sum = 0, best = long.MinValue;
        for (int right = 0; right < values.Length; right++)
        {
            sum += values[right];
            if (right >= k) sum -= values[right - k];
            if (right >= k - 1) best = Math.Max(best, sum);
        }
        return best;
    }
    // UTF-16 code units; returns a length, not a substring or start index.
    public static int LongestAtMostKDistinct(string text, int k)
    {
        ArgumentNullException.ThrowIfNull(text);
        if (k < 0) throw new ArgumentOutOfRangeException(nameof(k));
        var counts = new Dictionary<char, int>();
        int left = 0, best = 0;
        for (int right = 0; right < text.Length; right++)
        {
            counts[text[right]] = counts.GetValueOrDefault(text[right]) + 1;
            while (counts.Count > k)
            {
                char c = text[left++];
                if (--counts[c] == 0) counts.Remove(c);
            }
            best = Math.Max(best, right - left + 1);
        }
        return best;
    }
    // Shortest subarray with sum >= target. Requires strictly positive values.
    public static int MinPositiveLength(int[] values, long target)
    {
        ArgumentNullException.ThrowIfNull(values);
        if (target <= 0) throw new ArgumentOutOfRangeException(nameof(target));
        foreach (int value in values) if (value <= 0) throw new ArgumentException("Positive values required.");
        int left = 0, best = int.MaxValue;
        long sum = 0;
        for (int right = 0; right < values.Length; right++)
        {
            sum += values[right];
            while (sum >= target)
            {
                best = Math.Min(best, right - left + 1);
                sum -= values[left++];
            }
        }
        return best == int.MaxValue ? 0 : best;
    }
}

using System;
using System.Collections.Generic;
public static class PrefixSums
{
    // All inputs and target are int; long safely holds sums/counts for int-indexed arrays.
    public static long CountTargetSum(int[] values, int target)
    {
        ArgumentNullException.ThrowIfNull(values);
        var counts = new Dictionary<long, long> { [0] = 1 };
        long sum = 0, answer = 0;
        foreach (int value in values)
        {
            sum += value;
            answer += counts.GetValueOrDefault(sum - target);
            counts[sum] = counts.GetValueOrDefault(sum) + 1;
        }
        return answer;
    }
    // prefix[i] sums values[0..i); query [left,right) as prefix[right]-prefix[left].
    public static long[] Build(int[] values)
    {
        ArgumentNullException.ThrowIfNull(values);
        var prefix = new long[checked(values.Length + 1)];
        for (int i = 0; i < values.Length; i++) prefix[i + 1] = prefix[i] + values[i];
        return prefix;
    }
}

using System;
using System.Collections.Generic;
public static class LinkedLists
{
    public sealed class Node
    {
        public int Value;
        public Node? Next;
        public Node(int value, Node? next = null) { Value = value; Next = next; }
    }
    public static bool HasCycle(Node? head)
    {
        Node? slow = head, fast = head;
        while (fast?.Next != null)
        {
            slow = slow!.Next;
            fast = fast.Next.Next;
            if (ReferenceEquals(slow, fast)) return true;
        }
        return false;
    }
    // Acyclic list required. Even length returns the SECOND middle; null -> null.
    public static Node? Middle(Node? head)
    {
        Node? slow = head, fast = head;
        while (fast?.Next != null) { slow = slow!.Next; fast = fast.Next.Next; }
        return slow;
    }
    // Acyclic list required; mutates and reuses existing nodes.
    public static Node? Reverse(Node? head)
    {
        Node? previous = null, current = head;
        while (current != null)
        {
            Node? next = current.Next;
            current.Next = previous;
            previous = current;
            current = next;
        }
        return previous;
    }
    // Sorted, acyclic, DISJOINT lists required. Mutates/reuses their nodes.
    public static Node? Merge(Node? a, Node? b)
    {
        var dummy = new Node(0);
        Node tail = dummy;
        while (a != null && b != null)
        {
            if (a.Value <= b.Value) { tail.Next = a; a = a.Next; }
            else { tail.Next = b; b = b.Next; }
            tail = tail.Next;
        }
        tail.Next = a ?? b;
        return dummy.Next;
    }
    // Reverse inclusive 1-based positions. Validates range before mutation.
    public static Node? ReverseRange(Node? head, int left, int right)
    {
        if (left < 1 || right < left) throw new ArgumentOutOfRangeException(nameof(left));
        int length = 0;
        for (Node? node = head; node != null; node = node.Next) length++;
        if (right > length) throw new ArgumentOutOfRangeException(nameof(right));
        var dummy = new Node(0, head);
        Node before = dummy;
        for (int i = 1; i < left; i++) before = before.Next!;
        Node tail = before.Next!;
        for (int i = 0; i < right - left; i++)
        {
            Node moved = tail.Next!;
            tail.Next = moved.Next;
            moved.Next = before.Next;
            before.Next = moved;
        }
        return dummy.Next;
    }

    // Sorted, acyclic, mutually disjoint lists; reuses and mutates nodes.
    public static Node? MergeMany(Node?[] heads)
    {
        ArgumentNullException.ThrowIfNull(heads);
        var heap = new PriorityQueue<Node,int>();
        foreach (Node? head in heads) if (head != null) heap.Enqueue(head,head.Value);
        var dummy = new Node(0); Node tail = dummy;
        while (heap.TryDequeue(out Node? node,out _))
        {
            Node? next = node.Next; tail.Next = node; tail = node;
            if (next != null) heap.Enqueue(next,next.Value);
        }
        tail.Next = null; return dummy.Next;
    }

}

using System;
using System.Collections.Generic;
public static class Stacks
{
    // Returns next STRICTLY greater VALUES, not indices or distances; -1 means absent.
    public static int[] NextGreaterValues(int[] values)
    {
        ArgumentNullException.ThrowIfNull(values);
        var answer = new int[values.Length];
        Array.Fill(answer, -1);
        var pending = new Stack<int>();
        for (int i = 0; i < values.Length; i++)
        {
            while (pending.Count > 0 && values[pending.Peek()] < values[i])
                answer[pending.Pop()] = values[i];
            pending.Push(i);
        }
        return answer;
    }
    // Any non-bracket character is invalid under this contract.
    public static bool ValidBrackets(string text)
    {
        ArgumentNullException.ThrowIfNull(text);
        var pending = new Stack<char>();
        foreach (char c in text)
        {
            if (c is '(' or '[' or '{') { pending.Push(c); continue; }
            char expected = c switch { ')' => '(', ']' => '[', '}' => '{', _ => '\0' };
            if (expected == '\0' || !pending.TryPop(out char open) || open != expected) return false;
        }
        return pending.Count == 0;
    }
    // Nonnegative heights. Returned area is long; virtual final zero flushes the stack.
    public static long LargestRectangle(int[] heights)
    {
        ArgumentNullException.ThrowIfNull(heights);
        foreach (int h in heights) if (h < 0) throw new ArgumentException("Nonnegative heights required.");
        var pending = new Stack<int>();
        long best = 0;
        for (int i = 0; i <= heights.Length; i++)
        {
            int height = i == heights.Length ? 0 : heights[i];
            while (pending.Count > 0 && heights[pending.Peek()] > height)
            {
                int h = heights[pending.Pop()];
                int left = pending.Count == 0 ? -1 : pending.Peek();
                best = Math.Max(best, (long)h * (i - left - 1));
            }
            if (i < heights.Length) pending.Push(i);
        }
        return best;
    }
    public static long TrappedWater(int[] heights)
    {
        ArgumentNullException.ThrowIfNull(heights);
        foreach (int h in heights) if (h < 0) throw new ArgumentException("Nonnegative heights required.");
        int left = 0, right = heights.Length - 1, leftMax = 0, rightMax = 0;
        long water = 0;
        while (left <= right)
        {
            if (leftMax <= rightMax)
            {
                leftMax = Math.Max(leftMax, heights[left]);
                water += leftMax - heights[left++];
            }
            else
            {
                rightMax = Math.Max(rightMax, heights[right]);
                water += rightMax - heights[right--];
            }
        }
        return water;
    }

    // Distance to next strictly warmer day; 0 means no warmer future day.
    public static int[] DaysUntilWarmer(int[] temperatures)
    {
        ArgumentNullException.ThrowIfNull(temperatures);
        var answer = new int[temperatures.Length]; var pending = new Stack<int>();
        for (int i = 0; i < temperatures.Length; i++)
        {
            while (pending.Count > 0 && temperatures[pending.Peek()] < temperatures[i])
            { int previous = pending.Pop(); answer[previous] = i - previous; }
            pending.Push(i);
        }
        return answer;
    }
    // Consecutive days ending today whose price is <= today's, including today.
    public static int[] StockSpans(int[] prices)
    {
        ArgumentNullException.ThrowIfNull(prices);
        var answer = new int[prices.Length]; var greater = new Stack<int>();
        for (int i = 0; i < prices.Length; i++)
        {
            while (greater.Count > 0 && prices[greater.Peek()] <= prices[i]) greater.Pop();
            answer[i] = greater.Count == 0 ? i + 1 : i - greater.Peek();
            greater.Push(i);
        }
        return answer;
    }

}

