        void Visit(Node? node)
        {
            if (node == null) { tokens.Add("#"); return; }
            tokens.Add(node.Value.ToString(CultureInfo.InvariantCulture)); Visit(node.Left); Visit(node.Right);
        }
        Visit(root); return string.Join(",",tokens);
    }
    public static Node? Deserialize(string data)
    {
        ArgumentNullException.ThrowIfNull(data);
        string[] tokens = data.Split(','); int index = 0;
        Node? Read()
        {
            if (index == tokens.Length) throw new FormatException("Truncated tree.");
            string token = tokens[index++]; if (token == "#") return null;
            int value = int.Parse(token,CultureInfo.InvariantCulture);
            var node = new Node(value); node.Left = Read(); node.Right = Read(); return node;
        }
        Node? root = Read(); if (index != tokens.Length) throw new FormatException("Trailing tokens."); return root;
    }

    // Known-present unique BST keys. Does not verify presence or BST validity.
    public static Node? BstLowestCommonAncestor(Node? root, int p, int q)
    {
        while (root != null)
        {
            if (p < root.Value && q < root.Value) root = root.Left;
            else if (p > root.Value && q > root.Value) root = root.Right;
            else return root;
        }
        return null;
    }
    public static int[] RightSideView(Node? root)
    {
        var levels = Levels(root); var answer = new int[levels.Count];
        for (int i = 0; i < levels.Count; i++) answer[i] = levels[i][^1];
        return answer;
    }
    public static List<int[]> ZigzagLevels(Node? root)
    {
        var levels = Levels(root);
        for (int i = 1; i < levels.Count; i += 2) Array.Reverse(levels[i]);
        return levels;
    }

}

using System;
using System.Collections.Generic;
public static class Matrices
{
    private static int Width(int[][] grid)
    {
        ArgumentNullException.ThrowIfNull(grid);
        int n = grid.Length == 0 ? 0 : (grid[0] ?? throw new ArgumentException("Null row.")).Length;
        foreach (var row in grid) if (row == null || row.Length != n) throw new ArgumentException("Rectangular grid required.");
        return n;
    }
    public static int[] Spiral(int[][] grid)
    {
        int n = Width(grid); var result = new List<int>();
        int top = 0, bottom = grid.Length-1, left = 0, right = n-1;
        while (top <= bottom && left <= right)
        {
            for (int c = left; c <= right; c++) result.Add(grid[top][c]); top++;
            for (int r = top; r <= bottom; r++) result.Add(grid[r][right]); right--;
            if (top <= bottom) { for (int c = right; c >= left; c--) result.Add(grid[bottom][c]); bottom--; }
            if (left <= right) { for (int r = bottom; r >= top; r--) result.Add(grid[r][left]); left++; }
        }
        return result.ToArray();
    }
    // Mutates SQUARE grid, clockwise rotation.
    public static void RotateClockwise(int[][] grid)
    {
        int n = Width(grid); if (grid.Length != n) throw new ArgumentException("Square grid required.");
        for (int r = 0; r < n; r++) for (int c = r+1; c < n; c++) (grid[r][c],grid[c][r]) = (grid[c][r],grid[r][c]);
        foreach (var row in grid) Array.Reverse(row);
    }
    // Mutates grid. O(1) extra space, marking original zero rows/columns.
    public static void SetZeroes(int[][] grid)
    {
        int n = Width(grid), m = grid.Length; if (m == 0 || n == 0) return;
        bool firstRow = false, firstColumn = false;
        for (int c = 0; c < n; c++) if (grid[0][c] == 0) firstRow = true;
        for (int r = 0; r < m; r++) if (grid[r][0] == 0) firstColumn = true;
        for (int r = 1; r < m; r++) for (int c = 1; c < n; c++) if (grid[r][c] == 0) { grid[r][0] = 0; grid[0][c] = 0; }
        for (int r = 1; r < m; r++) for (int c = 1; c < n; c++) if (grid[r][0] == 0 || grid[0][c] == 0) grid[r][c] = 0;
        if (firstRow) Array.Fill(grid[0],0);
        if (firstColumn) for (int r = 0; r < m; r++) grid[r][0] = 0;
    }
}

using System;
public static class ArrayTricks
{
    // Contract: Length=n+1, every value in 1..n, exactly one distinct duplicated value.
    // Does not modify input. Range validated; uniqueness assumption is not validated.
    public static int Duplicate(int[] values)
    {
        ArgumentNullException.ThrowIfNull(values);
        if (values.Length < 2) throw new ArgumentException("At least two elements required.");
        foreach (int x in values) if (x < 1 || x >= values.Length) throw new ArgumentException("Values must be in 1..n.");
        int slow = values[0], fast = values[0];
        do { slow = values[slow]; fast = values[values[fast]]; } while (slow != fast);
        slow = values[0];
        while (slow != fast) { slow = values[slow]; fast = values[fast]; }
        return slow;
    }
    // Validates the candidate; returns null if no strict majority exists.
    public static int? Majority(int[] values)
    {
        ArgumentNullException.ThrowIfNull(values);
        int candidate = 0, balance = 0;
        foreach (int value in values)
        {
            if (balance == 0) candidate = value;
            balance += value == candidate ? 1 : -1;
        }
        int frequency = 0; foreach (int value in values) if (value == candidate) frequency++;
        return frequency > values.Length / 2 ? candidate : null;
    }
    // No division. Empty -> empty; singleton -> [1]. All intermediate products must fit long.
    public static long[] ProductExceptSelf(int[] values)
    {
        ArgumentNullException.ThrowIfNull(values);
        var result = new long[values.Length]; long product = 1;
        for (int i = 0; i < values.Length; i++)
        {
            result[i] = product;
            if (i < values.Length-1) product = checked(product * values[i]);
        }
        product = 1;
        for (int i = values.Length-1; i >= 0; i--)
        {
            result[i] = checked(result[i] * product);
            if (i > 0) product = checked(product * values[i]);
        }
        return result;
    }
    // Every value appears twice except one. The contract is not validated.
    public static int SingleByXor(int[] values)
    {
        ArgumentNullException.ThrowIfNull(values);
        int answer = 0; foreach (int value in values) answer ^= value; return answer;
    }
    public static int SetBitCount(uint value)
    {
        int count = 0;
        while (value != 0) { value &= value - 1; count++; }
        return count;
    }
}

using System;
using System.Collections.Generic;
public static class Caches
{
    // Single-threaded interview cache. Capacity zero stores nothing.
    public sealed class Lru
    {
        private readonly int capacity;
        private readonly Dictionary<int,LinkedListNode<(int Key,int Value)>> index = new();
        private readonly LinkedList<(int Key,int Value)> recency = new();
        public Lru(int capacity) { if (capacity < 0) throw new ArgumentOutOfRangeException(nameof(capacity)); this.capacity = capacity; }
        public bool TryGet(int key, out int value)
        {
            if (!index.TryGetValue(key,out var node)) { value = default; return false; }
            recency.Remove(node); recency.AddFirst(node); value = node.Value.Value; return true;
        }
        public void Put(int key, int value)
        {
            if (capacity == 0) return;
            if (index.TryGetValue(key,out var node))
            {
                node.Value = (key,value); recency.Remove(node); recency.AddFirst(node); return;
            }
            node = recency.AddFirst((key,value)); index.Add(key,node);
            if (index.Count <= capacity) return;
            var evicted = recency.Last!; index.Remove(evicted.Value.Key); recency.RemoveLast();
        }
    }
    public sealed class MinStack
    {
        private readonly Stack<(int Value,int Min)> values = new();
        public int Count => values.Count;
        public void Push(int value) => values.Push((value,values.Count == 0 ? value : Math.Min(value,values.Peek().Min)));
        public int Pop() => values.Pop().Value;
        public int Peek() => values.Peek().Value;
        public int Minimum() => values.Peek().Min;
    }
}

using System;
public static class Greedy
{
    // At most one buy then one sell. Empty/no profitable trade -> 0.
    public static long BestSingleTrade(int[] prices)
    {
        ArgumentNullException.ThrowIfNull(prices);
        long lowest = long.MaxValue, best = 0;
        foreach (int price in prices) { lowest = Math.Min(lowest,price); best = Math.Max(best,(long)price-lowest); }
        return best;
    }
    // Max NONEMPTY contiguous subarray sum. Empty input is invalid.
    public static long MaximumSubarray(int[] values)
    {
        ArgumentNullException.ThrowIfNull(values);
        if (values.Length == 0) throw new ArgumentException("Nonempty array required.");
        long endingHere = values[0], best = values[0];
        for (int i = 1; i < values.Length; i++) { endingHere = Math.Max(values[i],endingHere + values[i]); best = Math.Max(best,endingHere); }
        return best;
    }
    // Each nonnegative entry is maximum forward jump. Empty input -> false.
    public static bool CanReachEnd(int[] jumps)
    {
        ArgumentNullException.ThrowIfNull(jumps);
        foreach (int jump in jumps) if (jump < 0) throw new ArgumentException("Nonnegative jumps required.");
        long farthest = 0;
        for (int i = 0; i < jumps.Length && i <= farthest; i++)
        {
            farthest = Math.Max(farthest,(long)i+jumps[i]);
            if (farthest >= jumps.Length-1) return true;
        }
        return false;
    }
}

